<script setup lang="tsx">
import { ref, onMounted, watch, computed } from "vue";
import type { BaseTableCol, TableRowData } from "tdesign-vue-next";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips } from "@/util/tips";
import { GetBotGameList, ParseBotGame } from "@/apis/bot.ts";
import type { BotGame, BotGameView } from "@/types/bot.ts";
import type { CellParams } from "@/types/table";

const { globalProperties } = useCurrentInstance();

// Props
const props = withDefaults(defineProps<{
  visible: boolean;
  title?: string;
  showSearch?: boolean;
  showClearButton?: boolean;
  tableHeight?: number | string;
  columns?: BaseTableCol<TableRowData>[];
  dataLoader?: () => Promise<BotGameView[]>;
}>(), {
  title: '选择游戏',
  showSearch: true,
  showClearButton: true,
  tableHeight: 400,
  columns: () => []
});

// Events
const emit = defineEmits<{
  "update:visible": [value: boolean];
  "select": [game: BotGameView];
  "clear": [];
  "close": [];
}>();

// 游戏列表数据
const gameList = ref<BotGameView[]>([]);
const gameLoading = ref(false);
const gameSearchForm = ref({
  gameKey: "",
  title: ""
});

// 默认游戏列表列定义
const defaultColumns: BaseTableCol<TableRowData>[] = [
  { colKey: 'gameKey', title: '游戏标识', width: 200 },
  { colKey: 'title', title: '游戏名称', width: 300 },
  { colKey: 'introduction', title: '游戏描述', ellipsis: true },
  { colKey: 'playerMin', title: '最小玩家数', width: 100 },
  { colKey: 'playerMax', title: '最大玩家数', width: 100 },
  { 
    title: '操作', 
    colKey: 'action', 
    width: 100,
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return (
        <t-space>
          {/* 列定义使用通用行类型，此表格的数据源实际为 BotGameView */}
          <t-button theme="primary" size="small" onClick={() => handleGameSelect(data.row as BotGameView)}>
            选择
          </t-button>
        </t-space>
      );
    }
  }
];

// 使用默认列或用户提供的列
const gameColumns = computed(() => {
  return props.columns.length > 0 ? props.columns : defaultColumns;
});

// 加载游戏列表
const loadGameList = async () => {
  gameLoading.value = true;
  try {
    if (props.dataLoader) {
      // 使用用户自定义的数据加载器
      gameList.value = await props.dataLoader();
    } else {
      // 使用默认的API调用
      const response = await GetBotGameList();
      if (response.code === 0) {
        gameList.value = response.data.map((item: BotGame) => ParseBotGame(item));
      } else {
        ShowErrorTips(globalProperties, response.code);
      }
    }
  } catch (error) {
    ShowErrorTips(globalProperties, "加载游戏列表失败");
  } finally {
    gameLoading.value = false;
  }
};

// 处理游戏选择
const handleGameSelect = (record: BotGameView) => {
  emit('select', record);
  emit('update:visible', false);
};

// 游戏搜索表单提交
const handleGameSearchFormSubmit = async () => {
  if (props.dataLoader) {
    // 如果有自定义数据加载器，我们简单调用它
    // 用户可以在自己的数据加载器中实现搜索逻辑
    loadGameList();
  } else {
    // 使用默认的API调用（当前API不支持搜索参数）
    // 这里可以根据后端API的支持情况进行扩展
    loadGameList();
  }
};

// 游戏搜索表单重置
const handleGameSearchFormReset = () => {
  gameSearchForm.value.gameKey = "";
  gameSearchForm.value.title = "";
  loadGameList();
};

// 当对话框显示时加载游戏列表
onMounted(() => {
  if (props.visible) {
    loadGameList();
  }
});

// 监听visible属性变化，当显示时加载游戏列表
watch(() => props.visible, (newValue) => {
  if (newValue) {
    loadGameList();
  }
});

// 清除选中的游戏
const clearSelectedAgent = () => {
  emit('clear');
};

// 对话框可见性变化（显式声明参数类型，避免模板内隐式 any）
const handleVisibleUpdate = (value: boolean) => {
  emit('update:visible', value);
};
</script>

<template>
  <t-dialog 
    :visible="visible" 
    :footer="false" 
    :width="1300" 
    :header="title"
    @update:visible="handleVisibleUpdate"
    @close="() => {
      emit('update:visible', false);
      emit('close');
    }"
  >
    <!-- 搜索表单，根据showSearch prop决定是否显示 -->
    <t-form v-if="showSearch" layout="inline" @submit="handleGameSearchFormSubmit" @reset="handleGameSearchFormReset">
      <t-form-item label="游戏标识">
        <t-input v-model="gameSearchForm.gameKey" placeholder="请输入游戏标识" />
      </t-form-item>
      <t-form-item label="游戏名称">
        <t-input v-model="gameSearchForm.title" placeholder="请输入游戏名称" />
      </t-form-item>
      <t-form-item>
        <t-space>
            <t-button theme="primary" type="submit">搜索</t-button>
            <t-button theme="default" variant="base" type="reset">重置</t-button>
            <t-button v-if="showClearButton" theme="danger" @click="clearSelectedAgent">清除</t-button>
          </t-space>
      </t-form-item>
    </t-form>
    
    <!-- 游戏列表表格 -->
    <t-table 
      :columns="gameColumns" 
      :data="gameList" 
      row-key="id" 
      :loading="gameLoading"
    ></t-table>
  </t-dialog>
</template>